#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int scores[] = {4, 7, 2};
    int total = 0;
    for (int i = 0; i < 3; i++) {
        total += scores[i];
    }
    printf("%d\n", total);
    return 0;
}

#include <iostream>

int main() {
    int scores[] = {4, 7, 2};
    int total = 0;
    for (int score : scores) {
        total += score;
    }
    std::cout << total << '\n';
    return 0;
}

int[] scores = { 4, 7, 2 };
int total = 0;
foreach (int score in scores)
{
    total += score;
}
System.Console.WriteLine(total);

public class Main {
